// Mirrors the SQL function session_charge() in supabase/migrations/0002_billing.sql.
// Change both together; the unit tests (pricing.spec.ts, pricing.golden.spec.ts) cover this file
// and the golden values were generated by session_charge itself.
//
// Overtime on a package (migration 0023): time past the package is free while it is within the grace period
// (overtime_grace_min, copied to the session when it starts), unless staff chose to charge it (overtime_mode 'charge');
// staff can also waive it ('waive'). Overtime that is charged is rounded up to the billing block at the hourly rate.
// Staff can also type an amount for overtime that is within the grace (overtime_amount); beyond the grace the block charge applies.
// A session with no grace value (older golden rows) behaves as grace 0, exactly as before.
//
// Rules: played time = elapsed - paused. Per hour: round up to the billing block, at least the
// minimum bill. Package: fixed price inside the package minutes; overtime in billing blocks at the
// hourly rate. Pass: unlimited = 0; hours bundle = time beyond the balance at the hourly rate. The rate, block and minimum are the values snapshotted when the session started.
// Money is calculated in whole paise with integers and rounded half up, like Postgres numeric.

export interface SessionSnapshot {
  rate_per_hour: number | string;
  block_min: number;
  min_bill_min: number;
  package_minutes: number | null;
  package_price: number | string | null;
  /** Set when the session runs on a pass; pass_minutes_left null = unlimited pass. */
  pass_id?: number | null;
  pass_minutes_left?: number | null;
  /** minutes past the package that are not charged unless staff choose to (missing = 0) */
  overtime_grace_min?: number | null;
  /** staff's choice on this session: charge the overtime, waive it, or null for automatic */
  overtime_mode?: 'charge' | 'waive' | null;
  /** rupees staff typed for overtime within the grace (used only with overtime_mode 'charge') */
  overtime_amount?: number | string | null;
  started_at: string;
  paused_at: string | null;
  paused_seconds: number;
  ended_at: string | null;
}

const toPaise = (v: number | string): number => Math.round(Number(v) * 100);
const toMs = (iso: string): number => Date.parse(iso);
const roundHalfUp = (num: number, den: number): number => Math.floor((2 * num + den) / (2 * den));

/** Milliseconds actually played at endMs (paused time removed, never negative). */
export function playedMs(s: SessionSnapshot, endMs: number): number {
  const runningPause = s.paused_at ? endMs - toMs(s.paused_at) : 0;
  return Math.max(0, endMs - toMs(s.started_at) - s.paused_seconds * 1000 - runningPause);
}

/** True when overtime of `overMs` (> 0) is billed: staff said charge, or no choice was made and it is beyond the grace. */
export function overtimeCharged(s: SessionSnapshot, overMs: number): boolean {
  if (s.overtime_mode === 'waive') return false;
  if (s.overtime_mode === 'charge') return true;
  return overMs > (s.overtime_grace_min ?? 0) * 60_000;
}

/** The amount staff typed for overtime (in paise) when it applies: charging, with an amount, and still inside the grace. Otherwise null. */
export function customOvertimePaise(s: SessionSnapshot, overMs: number): number | null {
  if (s.overtime_mode !== 'charge' || s.overtime_amount == null || s.overtime_amount === '') return null;
  if (overMs > (s.overtime_grace_min ?? 0) * 60_000) return null;
  return toPaise(s.overtime_amount);
}

export interface OvertimeState {
  /** whole minutes past the package, rounded up */
  overMinutes: number;
  /** true when it is on the bill */
  charged: boolean;
  /** true when it is inside the grace period (so, with no staff choice, it is free) */
  withinGrace: boolean;
  /** rupees added to the bill if the overtime is charged the normal way (rounded up to the billing block) */
  ifChargedRupees: number;
  /** the amount staff typed, when it is the one on the bill; otherwise null */
  customRupees: number | null;
  mode: 'charge' | 'waive' | null;
}

/** What to show staff about overtime on a package session, or null when it is not in overtime. */
export function overtimeState(s: SessionSnapshot, endMs: number): OvertimeState | null {
  if (s.package_minutes === null || s.pass_id != null) return null;
  const over = playedMs(s, endMs) - s.package_minutes * 60_000;
  if (over <= 0) return null;
  const blockMs = s.block_min * 60_000;
  const blocks = Math.ceil(over / blockMs) * s.block_min;
  return {
    overMinutes: Math.ceil(over / 60_000),
    charged: overtimeCharged(s, over),
    withinGrace: over <= (s.overtime_grace_min ?? 0) * 60_000,
    ifChargedRupees: roundHalfUp(blocks * toPaise(s.rate_per_hour), 60) / 100,
    customRupees: customOvertimePaise(s, over) === null ? null : (customOvertimePaise(s, over) as number) / 100,
    mode: s.overtime_mode ?? null,
  };
}

/** The charge in paise at endMs. */
export function chargePaise(s: SessionSnapshot, endMs: number): number {
  const rate = toPaise(s.rate_per_hour);
  const blockMs = s.block_min * 60_000;
  const roundedMinutes = (ms: number): number => Math.ceil(ms / blockMs) * s.block_min;
  const played = playedMs(s, endMs);

  // pass session: unlimited is free; an hours bundle covers time up to its balance, the rest is billed
  // at the hourly rate (no minimum bill)
  if (s.pass_id != null) {
    if (s.pass_minutes_left == null) return 0;
    return roundHalfUp(Math.max(0, roundedMinutes(played) - s.pass_minutes_left) * rate, 60);
  }

  if (s.package_minutes !== null) {
    const price = toPaise(s.package_price ?? 0);
    const packageMs = s.package_minutes * 60_000;
    const over = played - packageMs;
    if (over <= 0 || !overtimeCharged(s, over)) return price;
    const custom = customOvertimePaise(s, over);
    if (custom !== null) return price + custom;
    return price + roundHalfUp(roundedMinutes(over) * rate, 60);
  }

  const minutes = Math.max(roundedMinutes(played), s.min_bill_min);
  return roundHalfUp(minutes * rate, 60);
}

/** The charge in rupees at endMs. */
export function sessionCharge(s: SessionSnapshot, endMs: number): number {
  return chargePaise(s, endMs) / 100;
}

/** An ended session is frozen at ended_at; an open one runs until now. */
export function chargeEndMs(s: SessionSnapshot, nowMs: number): number {
  return s.ended_at ? toMs(s.ended_at) : nowMs;
}

/** Package time left in ms (negative = overtime), or null for a per-hour session. */
export function packageRemainingMs(s: SessionSnapshot, endMs: number): number | null {
  if (s.package_minutes === null) return null;
  return s.package_minutes * 60_000 - playedMs(s, endMs);
}

/** 3725000 -> "1:02:05" */
export function formatDuration(ms: number): string {
  const total = Math.max(0, Math.floor(Math.abs(ms) / 1000));
  const h = Math.floor(total / 3600);
  const m = Math.floor((total % 3600) / 60);
  const sec = total % 60;
  return `${h}:${String(m).padStart(2, '0')}:${String(sec).padStart(2, '0')}`;
}
